{"implementation":"def solve(case):
    from fractions import Fraction

    segments = case["segments"]
    count = len(segments)
    if count == 0:
        return {"allocations": [], "by_name": {}, "total": 0}

    capacities = [max(0, int(segment["capacity"])) for segment in segments]
    minimums = [
        min(capacities[i], max(0, int(segment["minimum"])))
        for i, segment in enumerate(segments)
    ]
    weights = [max(0, int(segment["importance"])) for segment in segments]
    target = min(max(0, int(case["budget"])), sum(capacities))

    if target < sum(minimums):
        allocations = [0] * count
        remaining = target
        active = {i for i in range(count) if minimums[i] > 0}
        while remaining and active:
            total_weight = sum(weights[i] for i in active)
            if total_weight == 0:
                total_weight = len(active)
                effective = {i: 1 for i in active}
            else:
                effective = {i: weights[i] for i in active}
            quotas = {
                i: Fraction(remaining * effective[i], total_weight)
                for i in active
            }
            added = 0
            for i in active:
                amount = min(minimums[i] - allocations[i], int(quotas[i]))
                allocations[i] += amount
                added += amount
            remaining -= added
            if remaining:
                order = sorted(
                    active,
                    key=lambda i: (-(quotas[i] - int(quotas[i])), i),
                )
                progressed = False
                for i in order:
                    if remaining == 0:
                        break
                    if allocations[i] < minimums[i]:
                        allocations[i] += 1
                        remaining -= 1
                        progressed = True
                if not progressed:
                    break
            active = {i for i in active if allocations[i] < minimums[i]}
    else:
        allocations = minimums[:]
        remaining = target - sum(allocations)
        active = {i for i in range(count) if allocations[i] < capacities[i]}

        while remaining and active:
            total_weight = sum(weights[i] for i in active)
            effective = (
                {i: weights[i] for i in active}
                if total_weight
                else {i: 1 for i in active}
            )
            total_weight = sum(effective.values())
            capped = []
            for i in active:
                room = capacities[i] - allocations[i]
                share = Fraction(remaining * effective[i], total_weight)
                if share >= room:
                    capped.append(i)
            if capped:
                for i in capped:
                    room = capacities[i] - allocations[i]
                    allocations[i] += room
                    remaining -= room
                    active.remove(i)
                continue

            quotas = {
                i: Fraction(remaining * effective[i], total_weight)
                for i in active
            }
            added = 0
            for i in active:
                amount = int(quotas[i])
                allocations[i] += amount
                added += amount
            remaining -= added
            order = sorted(
                active,
                key=lambda i: (-(quotas[i] - int(quotas[i])), i),
            )
            for i in order:
                if remaining == 0:
                    break
                if allocations[i] < capacities[i]:
                    allocations[i] += 1
                    remaining -= 1
            break

    by_name = {
        segment["name"]: allocations[i]
        for i, segment in enumerate(segments)
    }
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": sum(allocations),
    }
"}
